import{_ as e,o as i,c as n,a as t}from"./app.ed6fc70e.js";var a="/aktivitaeten/BDM-2026-07/00_07-2026.jpg",r="/aktivitaeten/BDM-2026-07/01_07-2026.jpg",s="/aktivitaeten/BDM-2026-07/02_07-2026.jpg",d="/aktivitaeten/BDM-2026-07/03_07-2026.jpg",m="/aktivitaeten/BDM-2026-07/04_07-2026.jpg",l="/aktivitaeten/BDM-2026-07/05_07-2026.jpg",o="/aktivitaeten/BDM-2026-07/06_07-2026.jpg",g="/aktivitaeten/BDM-2026-07/07_07-2026.jpg",u="/aktivitaeten/BDM-2026-07/08_07-2026.jpg",h="/aktivitaeten/BDM-2026-07/09_07-2026.jpg",p="/aktivitaeten/BDM-2026-07/10_07-2026.jpg",c="/aktivitaeten/BDM-2026-07/11_07-2026.jpg",_="/aktivitaeten/BDM-2026-07/12_07-2026.jpg",k="/aktivitaeten/BDM-2026-07/13_07-2026.jpg",v="/aktivitaeten/BDM-2026-07/14_07-2026.jpg",B="/aktivitaeten/BDM-2026-07/15_07-2026.jpg",M="/aktivitaeten/BDM-2026-07/16_07-2026.jpg",D="/aktivitaeten/BDM-2026-07/17_07-2026.jpg",b="/aktivitaeten/BDM-2026-07/18_07-2026.jpg",f="/aktivitaeten/BDM-2026-07/19_07-2026.jpg",w="/aktivitaeten/BDM-2026-07/20_07-2026.jpg",j="/aktivitaeten/BDM-2026-07/21_07-2026.jpg",A="/aktivitaeten/BDM-2026-07/22_07-2026.jpg",S="/aktivitaeten/BDM-2026-07/23_07-2026.jpg",z="/aktivitaeten/BDM-2026-07/24_07-2026.jpg",E="/aktivitaeten/BDM-2026-07/25_07-2026.jpg",T="/aktivitaeten/BDM-2026-07/26_07-2026.jpg",F="/aktivitaeten/BDM-2026-07/27_07-2026.jpg",L="/aktivitaeten/BDM-2026-07/28_07-2026.jpg",P="/aktivitaeten/BDM-2026-07/29_07-2026.jpg",O="/aktivitaeten/BDM-2026-07/30_07-2026.jpg",W="/aktivitaeten/BDM-2026-07/31_07-2026.jpg",G="/aktivitaeten/BDM-2026-07/32_07-2026.jpg",H="/aktivitaeten/BDM-2026-07/33_07-2026.jpg",C="/aktivitaeten/BDM-2026-07/34_07-2026.jpg",K="/aktivitaeten/BDM-2026-07/35_07-2026.jpg",q="/aktivitaeten/BDM-2026-07/36_07-2026.jpg",Q="/aktivitaeten/BDM-2026-07/37_07-2026.jpg",N="/aktivitaeten/BDM-2026-07/38_07-2026.jpg",V="/aktivitaeten/BDM-2026-07/39_07-2026.jpg",J="/aktivitaeten/BDM-2026-07/40_07-2026.jpg",R="/aktivitaeten/BDM-2026-07/41_07-2026.jpg",X="/aktivitaeten/BDM-2026-07/42_07-2026.jpg",I="/aktivitaeten/BDM-2026-07/43_07-2026.jpg",U="/aktivitaeten/BDM-2026-07/44_07-2026.jpg",x="/aktivitaeten/BDM-2026-07/45_07-2026.jpg",y="/aktivitaeten/BDM-2026-07/46_07-2026.jpg",Z="/aktivitaeten/BDM-2026-07/47_07-2026.jpg",Y="/aktivitaeten/BDM-2026-07/48_07-2026.jpg",$="/aktivitaeten/BDM-2026-07/49_07-2026.jpg",ee="/aktivitaeten/BDM-2026-07/50_07-2026.jpg",ie="/aktivitaeten/BDM-2026-07/51_07-2026.jpg",ne="/aktivitaeten/BDM-2026-07/52_07-2026.jpg",te="/aktivitaeten/BDM-2026-07/53_07-2026.jpg",ae="/aktivitaeten/BDM-2026-07/54_07-2026.jpg",re="/aktivitaeten/BDM-2026-07/55_07-2026.jpg",se="/aktivitaeten/BDM-2026-07/56_07-2026.jpg",de="/aktivitaeten/BDM-2026-07/57_07-2026.jpg",me="/aktivitaeten/BDM-2026-07/58_07-2026.jpg",le="/aktivitaeten/BDM-2026-07/59_07-2026.jpg",oe="/aktivitaeten/BDM-2026-07/60_07-2026.jpg",ge="/aktivitaeten/BDM-2026-07/61_07-2026.jpg",ue="/aktivitaeten/BDM-2026-07/62_07-2026.jpg",he="/aktivitaeten/BDM-2026-07/63_07-2026.jpg",pe="/aktivitaeten/BDM-2026-07/64_07-2026.jpg",ce="/aktivitaeten/BDM-2026-07/65_07-2026.jpg",_e="/aktivitaeten/BDM-2026-07/66_07-2026.jpg",ke="/aktivitaeten/BDM-2026-07/67_07-2026.jpg",ve="/aktivitaeten/BDM-2026-07/68_07-2026.jpg",Be="/aktivitaeten/BDM-2026-07/69_07-2026.jpg",Me="/aktivitaeten/BDM-2026-07/70_07-2026.jpg",De="/aktivitaeten/BDM-2026-07/71_07-2026.jpg",be="/aktivitaeten/BDM-2026-07/72_07-2026.jpg",fe="/aktivitaeten/BDM-2026-07/73_07-2026.jpg",we="/aktivitaeten/BDM-2026-07/74_07-2026.jpg",je="/aktivitaeten/BDM-2026-07/75_07-2026.jpg",Ae="/aktivitaeten/BDM-2026-07/76_07-2026.jpg";const Se={},ze=t('<h1 id="bilder-des-monats-juli-2026" tabindex="-1"><a class="header-anchor" href="#bilder-des-monats-juli-2026" aria-hidden="true">#</a> Bilder des Monats Juli 2026</h1><hr><p>Die HamRadio 2026 war erneut ein tolles Erlebnis. Besonders gefreut hat es mich, viele Funkfreunde wiederzusehen. Am besten gefallen hat mir der Stand von Drau\xDFenfunker.de. Dort war immer etwas los und es ergaben sich viele nette und interessante Gespr\xE4che.</p><p>Das Wochenende hat mich so motiviert, dass ich (Torsten DA6TW) dienstags nach einem stressigen B\xFCrotag direkt mit dem Fahrrad in den Deutsch-Franz\xF6sischen Garten gefahren bin. Dort konnte ich erfolgreich zwei Parks (DE-0192 und DE-0151) sowie vier Bunker (B/DL-0203, B/DL-0204, B/DL-0205 und B/DL-0483) aktivieren.</p><p>Gearbeitet wurde auf dem 15-m-Band mit dem Yaesu FT-891 und der Drau\xDFenfunker-Teleskopantenne. Zun\xE4chst habe ich in SSB CQ gerufen. Aufgrund eines St\xF6rpegels von S3 bis S5 kamen jedoch kaum Stationen durch. Deshalb habe ich das Band abgesucht und drei starke Stationen gearbeitet. Der anschlie\xDFende Wechsel auf FT4 brachte weitere 29 QSOs ins Log. Das Highlight war ein QSO mit Japan \xFCber eine Entfernung von knapp 9.500 Kilometern.</p><p>Auf 70 cm gab es zum Abschluss noch ein Ortsgespr\xE4ch in FM mit John (DK9JC).</p><p>Die Heimfahrt verlief anschlie\xDFend angenehm, auch wenn sie nach dem langen Tag durchaus anstrengend war.</p><p><strong>Fazit:</strong> Ein rundum gelungenes Funkwochenende mit einem ebenso gelungenen Start in die neue Woche.</p><p><img src="'+a+'" alt="Bilder des Monats"><img src="'+r+'" alt="Bilder des Monats"><img src="'+s+'" alt="Bilder des Monats"><img src="'+d+'" alt="Bilder des Monats"></p><hr><p>DF9HC nach langer Zeit mal wieder drau\xDFen am Home-Trail DE-0629 ein St\xFCck n\xE4her zum Kilo-Award.</p><p><img src="'+m+'" alt="Bilder des Monats"><img src="'+l+'" alt="Bilder des Monats"><img src="'+o+'" alt="Bilder des Monats"></p><hr><p>Heute stand bei DF6TG mal wieder etwas SOTA auf dem Stundenplan. Es ging aufs Fellhorn mit 2037m. DL/AL-097. Mit der neuen Seilbahn ging es rauf bis auf 1700m. Von dort aus,dann zu Fu\xDF in gut 1 Stunde weiter bis zum Gipfel auf 2037m. Wie auch gestern, Pfiff der Wind stramm mit bis zu 10 bis 12m/sec.Ob da \xFCberhaupt die Antenne hielt.........ausprobieren. Da ich dann etwas unterhalb vom Gipfelkreuz war,im Lee,war der Wind so gut wie nicht zu sp\xFCren. Schnell die Eigenbau vertikal aufgebaut,den XIEGU G90 an den 12ah Eremit angeklemmt,und schon gings los. Sch\xF6ne Signale auf 20m,und 40m waren das Ergebnis des kleinen aber feinen Aufbaus. Besonders gefreut hat mich auf 20m ein DF2DF mit DL3BOB. Als der Wind dann noch kr\xE4ftiger wurde,gings ans abbauen,und dann bequem mit der Seilbahn wieder zur\xFCck ins Tal. Tolle Verbindungen und ein grandioser Ausblick in die Allg\xE4uer Alpen,zaubern einem dann doch immer wieder ein L\xE4cheln ins Gesicht \u{1F600}</p><p><img src="'+g+'" alt="Bilder des Monats"><img src="'+u+'" alt="Bilder des Monats"><img src="'+h+'" alt="Bilder des Monats"><img src="'+p+'" alt="Bilder des Monats"><img src="'+c+'" alt="Bilder des Monats"><img src="'+_+'" alt="Bilder des Monats"><img src="'+k+'" alt="Bilder des Monats"><img src="'+v+'" alt="Bilder des Monats"><img src="'+B+'" alt="Bilder des Monats"><img src="'+M+'" alt="Bilder des Monats"></p><hr><p>DB7GKA bei der abendlichen Aktivierung (33 QSOs in CW) direkt am Rollfeld der ehemaligen Landebahn im Landschaftspark Hachinger Tal DE-0546. Die Abendsonne bescherte einen wundersch\xF6nen Blick in die s\xFCdlich gelegenen Alpen.</p><p><img src="'+D+'" alt="Bilder des Monats"><img src="'+b+'" alt="Bilder des Monats"><img src="'+f+'" alt="Bilder des Monats"><img src="'+w+'" alt="Bilder des Monats"></p><hr><p>Wieder ein freier Tag,wieder Sonne,und wieder richtig Lust auf Amateurfunk. Also was macht ein Draussenfunker.......Richtig! Er geht raus,um drau\xDFen zu Funken. Besser gesagt in die H\xF6he. &quot; Der Berg ruft &quot; DF6TG folgte diesem Ruf des Berges wieder einmal,und machte sich mit gepackten Rucksack auf den Weg. Ziel war dieses mal der Edelsberg 1624m bei Nesselwang im Allg\xE4u. SOTA DL/ AL-161. Es ging hoch mit der Alpspitzbahn. Oben angekommen, ging der Aufstieg zu Fu\xDF bis zum Gipfel. Mit im Gep\xE4ck war das &quot; kleine Besteck &quot; XIEGU 6100,6ah Eremit und die JPC-12. Schnell aufgebaut und auf 20m,waren die erforderlichen QSO gleich im Log. Weitere Verbindungen durch ganz Europa kamen so mit 10 Watt PEP ins Logbuch. Nach dem Abbau ging es noch r\xFCber zur Alpspitz,wo auf 2m und 70cm mit dem Handfunkger\xE4t noch einige nette Verbindungen dazu kamen. Wieder mal zufrieden,und wieder mal mit einem L\xE4cheln im Gesicht,schwebte ich per Sessellift wieder zur\xFCck ins Tal. Und immer wieder sagte ich mir:&quot; Was f\xFCr ein g....s Hobby &quot; 73,DF6TG</p><p><img src="'+j+'" alt="Bilder des Monats"><img src="'+A+'" alt="Bilder des Monats"><img src="'+S+'" alt="Bilder des Monats"><img src="'+z+'" alt="Bilder des Monats"><img src="'+E+'" alt="Bilder des Monats"><img src="'+T+'" alt="Bilder des Monats"><img src="'+F+'" alt="Bilder des Monats"><img src="'+L+'" alt="Bilder des Monats"><img src="'+P+'" alt="Bilder des Monats"><img src="'+O+'" alt="Bilder des Monats"><img src="'+W+'" alt="Bilder des Monats"><img src="'+G+'" alt="Bilder des Monats"></p><hr><p>DB6NL - heute hab ich meine erste Aktivierung komplett in cw versucht und das Handmic mal zuhause gelassen. In DE-0580 hab ich mir unter den B\xE4umen einen sch\xF6nen schattigen Platz gesucht. Auf die aktiven Rufe auf 30m und 20m kamen leider wenig Antworten aber einige Parks konnte ich aktiv jagen. Leider wurde am Ende die Zeit knapp und ich musste mit 4 QSOs per FT8 \u201Eauff\xFCllen\u201C. Das macht Lust auf mehr\u2026</p><p><img src="'+H+'" alt="Bilder des Monats"><img src="'+C+'" alt="Bilder des Monats"><img src="'+K+'" alt="Bilder des Monats"></p><hr><p>Gravelbike-Tour und POTA-Erstaktivierung von DE-1265 &quot;Gro\xDFe Wiese&quot; bei G\xFCtersloh. Am Rand eines Feldwegs bot sich eine Sitzgelegenheit mit Platz f\xFCr die EFHW, ausnahmsweise gab es dieses Mal eine reine FT8-Aktivierung. Dank der Endfed und des Tuners waren Bandwechsel unkompliziert m\xF6glich, so gab es am Ende 40 QSOs verteilt \xFCber 5 B\xE4nder im Log. (DL9CE)</p><p><img src="'+q+'" alt="Bilder des Monats"><img src="'+Q+'" alt="Bilder des Monats"><img src="'+N+'" alt="Bilder des Monats"><img src="'+V+'" alt="Bilder des Monats"><img src="'+J+'" alt="Bilder des Monats"><img src="'+R+'" alt="Bilder des Monats"></p><hr><p>Gestern und heute habe ich als VE3/DL9PK die Parks im Osten Torontos aktiviert. Die oberen 3 (Sunnybrook Park, Serena Gundy Park und Wilket Creek Park, CA-5670, CA-5895 und CA-5671) liegen fu\xDFl\xE4ufig beieinander. Angereist bin ich mit Bus und Bahn. Der \xF6ffentliche Nahverkehr in Toronto ist g\xFCnstig, einfach und komfortabel. Alle Fahrzeuge sind mit guten Klimaanlagen ausgestattet. Der Fahrpreis im Stadtgebiet betr\xE4gt f\xFCr 90 Minuten und beliebig viele Umstiege 3,30 CAD. Das sind etwa 2,50\u20AC. Ich habe wie immer meine EFHW in die B\xE4ume geschmissen. 3 interessierten Parkmitarbeitern habe ich das Hobby erkl\xE4ren d\xFCrfen. Ich hatte Sorge, dass es wegen der Antenne \xC4rger geben k\xF6nnte, aber man versicherte mir das sei kein Problem. Mein FT-891 hatte ich mithilfe zweier Steakmesser, einem Leatherman und meiner Partnerin zuvor am Miller Lake n\xF6rdlich von Toronto bei Parry Sound f\xFCr die Region-2-B\xE4nder modifiziert. Dort habe ich auch einige Tage aktiv aus unserer H\xFCtte am See gehunted. Nach den Aktivierungen der 3 n\xF6rdlichen Parks habe ich mir ein E-Bike von einer Bike-Sharing-Station genommen (0.20 $/Minute) und bin gen S\xFCden gefahren mit der Absicht den letzten Park (Tommy Thompson Park, CA-5559) zu aktivieren. Dem nahegelegenen Woodbine Beach konnte ich bei der Hitze jedoch nicht widerstehen und bin zusammen mit der Familie stattdessen dort ins Wasser geh\xFCpft. Heute bin ich nochmal los und habe CA-5559 nachgeholt. Toronto hat leider wenige POTA-Parks zu bieten, dennoch hat es mir viel Freude bereitet. Viele Hunter waren froh ein exotisches Call zu sammeln und es kamen unter anderem Haiti und Bahamas und einige 13-Colonies-Stationen ins Log. Ein gelungenes Funkabenteuer.</p><p><img src="'+X+'" alt="Bilder des Monats"><img src="'+I+'" alt="Bilder des Monats"><img src="'+U+'" alt="Bilder des Monats"><img src="'+x+'" alt="Bilder des Monats"><img src="'+y+'" alt="Bilder des Monats"><img src="'+Z+'" alt="Bilder des Monats"><img src="'+Y+'" alt="Bilder des Monats"><img src="'+$+'" alt="Bilder des Monats"><img src="'+ee+'" alt="Bilder des Monats"><img src="'+ie+'" alt="Bilder des Monats"></p><hr><p>Als Test, wie eine solche Aktion in einem Park angenommen wird, sind Brigitte, Wolfgang mit Kids, Tobias mit Kind und Frau und ich (Harm) am 18.07. im Hamburger Stadtpark aufgeschlagen und haben die Draussenfuchs Funkfuchssuche veranstaltet. Erkenntnis: Ohne aktive Werbung kommt kaum &quot;Laufkundschaft&quot;. Aber mit etwas Nachhelfen haben Familien und Kids dann viel Spa\xDF. Auf meiner Einkaufsliste: ein Banner &quot;jetzt kostenlos mitmachen und die Funkf\xFCchse finden&quot;</p><p>Nebenbei haben wir noch eine POTA-Aktivierung gemacht und so erfolgreich am Support your parks weekend teilgenommen.</p><p><img src="'+ne+'" alt="Bilder des Monats"><img src="'+te+'" alt="Bilder des Monats"><img src="'+ae+'" alt="Bilder des Monats"></p><hr><p>DL2XT hat am Freitag den Park DE-0297 erneut erfolgreich aktiviert. 20W mit dem Xiegu G90 auf dem 20m Band. Die Highlights neben der sch\xF6nen Location waren die Kontakte nach Luxemburg und Japan.</p><p><img src="'+re+'" alt="Bilder des Monats"><img src="'+se+'" alt="Bilder des Monats"><img src="'+de+'" alt="Bilder des Monats"><img src="'+me+'" alt="Bilder des Monats"><img src="'+le+'" alt="Bilder des Monats"><img src="'+oe+'" alt="Bilder des Monats"></p><hr><p>DN9GU, Andreas und ich DA6MAX, Max sind heute in den Taunus, f\xFCr einen 4fer. Als Spot hatten wir uns den Alteburger Markt ausgesucht, der mit einem gro\xDFen Parkplatz und einer gem\xFCtlichen Bank-Tisch-Kombination mitten in einer Streuobstwiese ideal gelegen ist. Ein gro\xDFes Dankesch\xF6n geht hier direkt an DB4SNK, Tomas f\xFCr die hervorragende Empfehlung dieses Spots!</p><p>Bei absolutem Kaiserwetter haben wir uns dort niedergelassen und unsere Stationen aufgebaut. Als Antennen kamen eine 1/4-Lambda-Vertical sowie ein vertikaler Dipol zum Einsatz. Andreas schlug mir dann vor, einfach mal auf 15 Meter anzufangen \u2013 und was dann passierte, habe ich so noch nicht erlebt: Ich hatte sofort einen konstanten Pileup in SSB! Wo man sonst manchmal z\xE4h um jedes einzelne QSO k\xE4mpfen muss, durfte ich heute im \u201Ekalten Wasser\u201C lernen, wie man einen richtigen Pileup managt. Es war eine wirklich geniale Erfahrung! Neben Verbindungen quer durch ganz Europa wanderte sogar ein DX-QSO r\xFCber in die USA nach Massachusetts ins Log.</p><p>Andreas war ebenfalls super erfolgreich. Er ging auf 10 Meter aktiv und konnte dort sein allererstes POTA QSO au\xDFerhalb Deutschlands auf diesem Band feiern \u2013 herzlichen Gl\xFCckwunsch an dieser Stelle f\xFCr die Verbindung nach UK sowie den tollen Park-to-Park (P2P) nach \xD6sterreich! Auf FT8 lief es bei ihm danach auch richtig rund, w\xE4hrend bei mir auf 15 Meter in Digimodes kaum was ging \u2013 immer wieder spannend zu sehen, wie unterschiedlich die B\xE4nder und Betriebsarten reagieren.</p><p>Insgesamt war das eine rundum gelungene Aktion an einer fantastischen Location, die wir wirklich jedem Drau\xDFenfunker nur w\xE4rmstens empfehlen k\xF6nnen. Insgesamt konnte Max 34 QSOs mit 22 DXCC-Entities ins Log eintragen und damit die vier Referenzen DE-0035, DE-0558, DE-0941 und DE-1197 erfolgreich aktivieren.</p><p>Ein dickes Dankesch\xF6n geht zum Schluss noch an unseren treuen Kai, DA6XJ, der uns immer wieder flei\xDFig mit seinen QSOs bei den Aktivierungen unterst\xFCtzt!</p><p><img src="'+ge+'" alt="Bilder des Monats"><img src="'+ue+'" alt="Bilder des Monats"><img src="'+he+'" alt="Bilder des Monats"><img src="'+pe+'" alt="Bilder des Monats"><img src="'+ce+'" alt="Bilder des Monats"><img src="'+_e+'" alt="Bilder des Monats"><img src="'+ke+'" alt="Bilder des Monats"><img src="'+ve+'" alt="Bilder des Monats"></p><hr><p>Ein sch\xF6ner Sommermorgen mit einem POTA 3fer aus der Mitte Bielefelds, oberhalb des Tierparks Olderdissen fand ich einen geeigneten Spot mitten im Wald mit einer Sitzgelegenheit und Platz f\xFCr die Vertikalantenne. Auf dem 20m-Band war wenig los, nach etwa einer halben Stunde Rufen hatte ich 11 QSOs im Log. Danach ging es dann auf 40m weiter, hier war dann deutlich mehr los und das Band insgesamt sehr st\xF6rungsfrei. (DL9CE)</p><p><img src="'+Be+'" alt="Bilder des Monats"><img src="'+Me+'" alt="Bilder des Monats"><img src="'+De+'" alt="Bilder des Monats"><img src="'+be+'" alt="Bilder des Monats"></p><hr><p>Eine Einreichung per E-Mail erreichte uns von Timm, DO2XU, f\xFCr seine Aktivierung im Juni:</p><p>Anbei noch ein paar Bilder f\xFCr den Monatsr\xFCckblick Juni. Spontan zur Mittagszeit einen 2fer aktiviert: DE-0630 und DE-0641 in der Stader Innenstadt. Mit dabei ein FT-891 und die DF-Vertical. Nach 19 Minuten waren die obligatorischen 10 QSOs auf 15 Meter eingesackt. Den kr\xF6nenden Abschluss bildete noch ein Park-to-Summit mit S57MS/p auf dem S5/RG-011 (1099m).</p><p>73, Timm DO2XU</p><p><img src="'+fe+'" alt="Bilder des Monats"><img src="'+we+'" alt="Bilder des Monats"><img src="'+je+'" alt="Bilder des Monats"><img src="'+Ae+'" alt="Bilder des Monats"></p>',52),Ee=[ze];function Te(Fe,Le){return i(),n("div",null,Ee)}var Oe=e(Se,[["render",Te],["__file","2026-07-30-Bilder-Des-Monats-Juli.html.vue"]]);export{Oe as default};
